Run required bounded offline baseline:
env:
  CI_HEAD: ${{ github.event.pull_request.head.sha || github.sha }}
  CI_BASE: ${{ github.event.pull_request.base.sha || github.event.before || '' }}
  SELECTION_ATTEMPT: ${{ needs.changes.outputs.attempt }}
run: python3 -B scripts/ci_baseline.py run --selection .ci/selection/selection.json --head "$CI_HEAD" --base "$CI_BASE" --selection-attempt "$SELECTION_ATTEMPT" --output .ci/baseline

Require successful change selection:
env:
  SELECTION_RESULT: ${{ needs.changes.result }}
  GAME_SELECTION: ${{ needs.changes.outputs.game }}
  EXTENSIVE_SELECTION: ${{ needs.changes.outputs.extensive }}
  GATING_SELECTION: ${{ needs.changes.outputs.gating }}
run: |
  test "$SELECTION_RESULT" = success
  case "$GAME_SELECTION" in true|false) ;; *) exit 1 ;; esac
  case "$EXTENSIVE_SELECTION" in true|false) ;; *) exit 1 ;; esac
  case "$GATING_SELECTION" in 0|1) ;; *) exit 1 ;; esac

Record compilation outcome and source re:
if: always()
env:
  CI_HEAD: ${{ github.event.pull_request.head.sha || github.sha }}
  CI_BASE: ${{ github.event.pull_request.base.sha || github.event.before || '' }}
  COMPILE_OUTCOME: ${{ steps.compile.outcome }}
  SELECTION_ATTEMPT: ${{ needs.changes.outputs.attempt }}
run: python3 -B scripts/ci_baseline.py compile --selection .ci/selection/selection.json --head "$CI_HEAD" --base "$CI_BASE" --outcome "$COMPILE_OUTCOME" --selection-attempt "$SELECTION_ATTEMPT" --output .ci/compile/compile.json
